<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { foundation, type Asset } from '@/api/foundation'
import SafeAnswer from '@/components/SafeAnswer.vue'
import { api } from '@/api/client'
import { useAuthStore } from '@/stores/auth'
import { messageOf } from '@/api/client'
import { learningApi } from '@/api/learning'
import type { Document, KnowledgePoint, LearningEvent, Mastery, Subject } from '@/api/types'
import { Drawer as TDrawer, MessagePlugin } from 'tdesign-vue-next'
const auth=useAuthStore(), editing=ref(false), draft=ref<KnowledgePoint|null>(null)
function newPoint(){const subject=subjects.value[0];if(!subject)return;draft.value={ID:'',SubjectID:subject.ID,ParentID:'',Code:subject.Code+'.',Name:'',Description:'',Keywords:[],SubjectName:subject.Name};selected.value=draft.value;editing.value=true}
async function savePoint(){if(!draft.value)return;try{const response=await api.request({method:draft.value.ID?'PUT':'POST',url:draft.value.ID?`/admin/knowledge-points/${draft.value.ID}`:'/admin/knowledge-points',data:draft.value});draft.value=response.data;editing.value=false;await load();await open(response.data)}catch(e){MessagePlugin.error(messageOf(e))}}

const subjects=ref<Subject[]>([]), points=ref<KnowledgePoint[]>([]), selected=ref<KnowledgePoint|null>(null)
const resources=ref<Document[]>([]), mastery=ref<Mastery|null>(null), events=ref<LearningEvent[]>([])
const assets=ref<Asset[]>([])
const lessons=computed(()=>assets.value.filter(a=>a.PointID===selected.value?.ID&&a.Kind==='material'))
function ordered(subjectID:string){const all=points.value.filter(p=>p.SubjectID===subjectID),seen=new Set<string>();const out:KnowledgePoint[]=[];function visit(p:KnowledgePoint){if(seen.has(p.ID))return;seen.add(p.ID);out.push(p);all.filter(c=>c.ParentID===p.ID).forEach(visit)}all.filter(p=>!p.ParentID).forEach(visit);all.forEach(visit);return out}
const grouped=computed(()=>subjects.value.map(subject=>({subject,points:ordered(subject.ID)})))
async function load(){try{[subjects.value,points.value]=await Promise.all([learningApi.subjects(),learningApi.points()])}catch(e){MessagePlugin.error(messageOf(e))}}
async function open(p:KnowledgePoint){selected.value=p;resources.value=[];mastery.value=null;events.value=[];try{const data=await learningApi.point(p.ID);if(selected.value?.ID!==p.ID)return;selected.value=data.knowledge_point;resources.value=data.resources;mastery.value=data.mastery;events.value=data.recent_events;await learningApi.viewPoint(p)}catch(e){MessagePlugin.error(messageOf(e))}}
onMounted(async()=>{await load();try{assets.value=await foundation.assets()}catch(e){MessagePlugin.error(messageOf(e))}})
</script>
<template><div><header class="page-head"><div><p class="eyebrow">408 KNOWLEDGE MAP</p><h1>408 知识体系</h1><p>按四科组织的教学图谱，记录前置关系、资源和学习状态。</p></div><button v-if="auth.user?.role==='admin'" class="primary" @click="newPoint">新增知识点</button></header><div class="grid knowledge-grid"><section class="card" v-for="g in grouped" :key="g.subject.ID"><span class="subject-code">{{g.subject.Code}}</span><h2>{{g.subject.Name}}</h2><div class="list"><div class="list-item kp" :style="{paddingLeft:p.ParentID?'24px':'0'}" v-for="p in g.points" :key="p.ID" @click="open(p)"><div class="grow"><b>{{p.Name}}</b><div class="reason">{{p.Description||p.Code}}</div></div><span>→</span></div></div></section></div><TDrawer :visible="!!selected" :header="selected?.Name" size="460px" @close="selected=null"><template v-if="selected"><p class="eyebrow">{{selected.SubjectName}} · {{selected.Code}}</p><p style="line-height:1.8">{{selected.Description||'知识点说明将在后续内容建设中继续完善。'}}</p><section v-for="lesson in lessons" :key="lesson.ID"><h3>{{lesson.Title}}</h3><SafeAnswer :text="lesson.Payload.Stem+'\n\n'+lesson.Payload.Explanation" :citations="0"/><p class="reason">{{lesson.Payload.Source}}</p><RouterLink :to="'/exam408/assessment'">进入测评与练习 →</RouterLink></section><button v-if="auth.user?.role==='admin'" class="secondary" @click="draft=JSON.parse(JSON.stringify(selected));editing=true">维护目录说明</button><form v-if="editing && draft" @submit.prevent="savePoint"><template v-if="!draft.ID"><label class="field">学科<select v-model="draft.SubjectID"><option v-for="s in subjects" :key="s.ID" :value="s.ID">{{s.Name}}</option></select></label><label class="field">上级目录<select v-model="draft.ParentID"><option value="">顶级目录</option><option v-for="p in points.filter(p=>p.SubjectID===draft?.SubjectID)" :key="p.ID" :value="p.ID">{{p.Name}}</option></select></label><label class="field">稳定代码<input v-model="draft.Code" required placeholder="例如 OS.NEW_POINT"/></label></template><label class="field">名称<input v-model="draft.Name" required /></label><label class="field">目录说明<textarea v-model="draft.Description" rows="5" /></label><button class="primary">保存目录</button></form><h4>识别关键词</h4><div style="display:flex;gap:8px;flex-wrap:wrap"><span class="pill" v-for="k in selected.Keywords" :key="k">{{k}}</span></div><div class="card" style="margin-top:18px"><b>当前掌握</b><p class="reason" v-if="mastery">掌握度 {{Math.round(mastery.MasteryScore*100)}}% · 薄弱度 {{Math.round(mastery.WeaknessScore*100)}}% · {{mastery.InteractionCount}} 次交互</p><p class="reason" v-else>尚无学习行为数据。</p></div><h4>关联资料</h4><div class="list"><div class="list-item" v-for="r in resources" :key="r.ID"><div class="grow"><b>{{r.OriginalFilename}}</b><div class="reason">{{r.ResourceType}} · {{r.Status}}</div></div></div><div v-if="!resources.length" class="reason">暂未关联资料。</div></div><h4>最近学习</h4><div class="list"><div class="list-item" v-for="e in events" :key="e.ID"><div class="grow"><b>{{e.EventType}}</b><div class="reason">{{new Date(e.CreatedAt).toLocaleString()}}</div></div></div><div v-if="!events.length" class="reason">暂无近期事件。</div></div></template></TDrawer></div></template>
